"""Run after editing assets/config/branding.json. Requires Python + Pillow."""
from pathlib import Path
import json
from PIL import Image, ImageDraw

root = Path(__file__).resolve().parents[1]
branding = json.loads((root / 'assets/config/branding.json').read_text())
(root / 'lib/app/config/branding.dart').write_text(
    '// Generated by scripts/sync_branding.py from assets/config/branding.json.\n'
    f'const applicationName = {json.dumps(branding["name"])};\n', encoding='utf-8')
manifest = dict(name=branding['name'], short_name=branding['shortName'], description=branding['description'], start_url='.', display='standalone', background_color=branding['backgroundColor'], theme_color=branding['themeColor'])
manifest['icons'] = [dict(src=f'icons/icon-{size}.png', sizes=f'{size}x{size}', type='image/png', purpose='any maskable') for size in [192, 512]]
(root / 'web/manifest.json').write_text(json.dumps(manifest, indent=2) + '\n', encoding='utf-8')
index = (root / 'web/index.html').read_text()
import re
import html
index = re.sub(r'<title>.*?</title>', f'<title>{html.escape(branding["name"])}</title>', index)
index = re.sub(r'<meta name="description" content="[^"]*">', f'<meta name="description" content="{html.escape(branding["description"], quote=True)}">', index)
(root / 'web/index.html').write_text(index, encoding='utf-8')
for size in [192, 512]:
    picture = Image.new('RGB', (size, size), branding['backgroundColor'])
    draw = ImageDraw.Draw(picture)
    def oval(box, color): draw.ellipse(tuple(round(v * size) for v in box), fill=color)
    green = branding['themeColor']
    for box in [(0.3,0.25,0.43,0.43),(0.56,0.25,0.69,0.43),(0.3,0.61,0.43,0.77),(0.56,0.61,0.69,0.77),(0.4,0.14,0.6,0.36)]: oval(box, green)
    oval((0.28,0.29,0.72,0.74), green)
    draw.regular_polygon((size*.5, size*.51, size*.13), 6, rotation=30, outline=branding['backgroundColor'], width=max(1,size//45))
    picture.save(root / f'web/icons/icon-{size}.png')
print('Branding, manifest and 192/512 PNG icons synchronised.')
